typedef struct station_view {                 /* hand-rolled view contract */
    const char *(*query)(void *ctx);
    void (*show_total)(void *ctx, double total);
    void *ctx;
} station_view;

void presenter_query_changed(struct app *a, station_view *v) {
    a->total = model_total(a->model, v->query(v->ctx));   /* read view, update model */
    v->show_total(v->ctx, a->total);                     /* drive the view */
}

