static void on_query_changed(GtkWidget *w, gpointer presenter) {
    MyView *view = MY_VIEW(w);
    presenter_refresh(presenter, my_view_get_query(view));
}
g_signal_connect(entry, "changed", G_CALLBACK(on_query_changed), presenter);
